window.RP_SESSION={"id":"S-6f423ef3ebe0","messages":[{"id":"RP-II-0094502","time":"2026-05-01T23:20:00+09:00","room":"RP II","name":"레디언트 렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"'우걱우걱-'\n\n 야심한 밤, 혼자 모닥불을 피우는 렉시. \n\n 강렬하게 타오르는 모닥불 위에 수프가 든 냄비와 고기를 올린 후, 음식이 맛있게 익을 때까지 기다립니다.\n\n...\n\n 몇 분 후, 고기와 수프가 다 익자, 미리 챙겨 온 작은 그릇에 수프를 덜고 고기에 꽂아놓은 막대기를 맨손으로 잡고 맛있게 먹기 시작하네요.","characters":["P-07a519db64cf"]},{"id":"RP-II-0094503","time":"2026-05-02T00:12:00+09:00","room":"RP II","name":"이파리","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"\"오 안녕하세요~\"\n맛있게 고기를 먹고 있는 렉시 뒤에서 이파리가 불쑥 나타납니다.","characters":["P-baa74cd42fe6"]},{"id":"RP-II-0094504","time":"2026-05-02T00:15:00+09:00","room":"RP II","name":"이파리","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"“오 어디에서 이렇게 맛있는 냄새가 나는가, 했더니 이곳에서 나는 냄새였군요!”\n\n이파리는 슬쩍 렉시 옆에 쭈그려 앉으며 모닥불 위 냄비를 들여다봅니다. 김이 모락모락 올라오는 수프에 눈이 반짝이네요.","characters":["P-baa74cd42fe6"]},{"id":"RP-II-0094505","time":"2026-05-02T00:15:00+09:00","room":"RP II","name":"레디언트 렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 왘- 놀래라! 귀신인 줄 알았네 \"\n\n\" 예, 반갑습니더~ \"\n\n 갑자기 뒤에서 나타난 그에게 악수를 청합니다.","characters":["P-07a519db64cf"]},{"id":"RP-II-0094506","time":"2026-05-02T00:18:00+09:00","room":"RP II","name":"이파리","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"이파리는 흔쾌히 렉시의 악수를 받아주며 말합니다.\n\n\"근데 이 수프는 재료가 뭔가요?\"","characters":["P-baa74cd42fe6"]},{"id":"RP-II-0094507","time":"2026-05-02T08:50:00+09:00","room":"RP II","name":"레디언트 렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-07a519db64cf"]},{"id":"RP-II-0094508","time":"2026-05-02T08:50:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
